import React, { useState } from 'react';
import { useMoods, useThoughts } from '../hooks/useStorage';

const MOOD_COLOR = { 1:'#8B3A3A', 2:'#8B5A3A', 3:'#6B6B3A', 4:'#2D6B6B', 5:'#3A6B8B' };

const S = {
  page: { background: '#EEEAE3', minHeight: '100vh', overflowY: 'auto' },
  inner: { padding: '56px 28px 110px' },
  lbl: { fontSize: 11, fontWeight: 600, color: 'rgba(26,42,42,0.3)', letterSpacing: '0.08em', textTransform: 'uppercase', marginBottom: 12 },
  h: { fontSize: 38, fontWeight: 700, letterSpacing: '-0.05em', lineHeight: 1.04, color: '#1A2A2A', marginBottom: 24 },
};

export default function History({ setPage }) {
  const { moods, streak }       = useMoods();
  const { thoughts, trapCounts } = useThoughts();
  const [expanded, setExpanded]  = useState(null);
  const isEmpty = moods.length === 0 && thoughts.length === 0;
  const maxTrap = Math.max(...Object.values(trapCounts), 1);

  if (isEmpty) return (
    <div style={{ ...S.page, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
      <div style={{ padding: '0 28px', textAlign: 'center' }}>
        <p style={{ fontSize: 18, color: 'rgba(26,42,42,0.4)', lineHeight: 1.6, marginBottom: 32 }}>Ingenting här än.<br />Skriv en tanke för att börja.</p>
        <button onClick={() => setPage('home')} style={{ padding: '16px 28px', borderRadius: 20, background: '#1A2A2A', color: '#EEEAE3', fontSize: 15, fontWeight: 600 }}>
          Analysera en tanke
        </button>
      </div>
    </div>
  );

  return (
    <div style={S.page}>
      <div style={S.inner}>
        <h2 style={S.h}>Historia.</h2>

        {/* Stats */}
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 8, marginBottom: 28 }}>
          {[
            { n: thoughts.length, l: 'Analyser' },
            { n: streak, l: 'Dagars streak', accent: true },
          ].map(({ n, l, accent }) => (
            <div key={l} style={{ padding: 20, borderRadius: 22, background: 'rgba(255,255,255,0.55)', border: '1px solid rgba(255,255,255,0.85)' }}>
              <div style={{ fontSize: 46, fontWeight: 700, letterSpacing: '-0.05em', color: accent ? '#2D6B6B' : '#1A2A2A', lineHeight: 1 }}>{n}</div>
              <div style={{ fontSize: 11, fontWeight: 600, color: 'rgba(26,42,42,0.3)', textTransform: 'uppercase', letterSpacing: '0.08em', marginTop: 4 }}>{l}</div>
            </div>
          ))}
        </div>

        {/* Mood bars */}
        {moods.length > 0 && (
          <>
            <div style={S.lbl}>Humör</div>
            <div style={{ display: 'flex', alignItems: 'flex-end', gap: 5, height: 48, marginBottom: 28 }}>
              {moods.slice(0, 14).reverse().map((m, i) => (
                <div key={i} style={{ flex: 1, borderRadius: 4, background: MOOD_COLOR[m.score] || '#2D6B6B', height: 10 + (m.score / 5) * 38, opacity: 0.3 + (m.score / 5) * 0.7 }} />
              ))}
            </div>
          </>
        )}

        {/* Trap counts */}
        {Object.keys(trapCounts).length > 0 && (
          <>
            <div style={S.lbl}>Tankefällor</div>
            <div style={{ marginBottom: 24 }}>
              {Object.entries(trapCounts).sort((a, b) => b[1] - a[1]).slice(0, 5).map(([label, count]) => (
                <div key={label} style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '13px 0', borderBottom: '1px solid rgba(26,42,42,0.06)' }}>
                  <span style={{ fontSize: 15, fontWeight: 500, color: '#1A2A2A', letterSpacing: '-0.02em' }}>{label}</span>
                  <span style={{ padding: '4px 12px', borderRadius: 999, background: 'rgba(45,107,107,0.1)', fontSize: 12, fontWeight: 600, color: '#2D6B6B' }}>{count}×</span>
                </div>
              ))}
            </div>
          </>
        )}

        {/* Thought log */}
        {thoughts.length > 0 && (
          <>
            <div style={S.lbl}>Logg</div>
            {thoughts.map((th, i) => (
              <div
                key={th.id}
                onClick={() => setExpanded(expanded === i ? null : i)}
                style={{ padding: 18, borderRadius: 20, marginBottom: 8, background: expanded === i ? 'rgba(255,255,255,0.75)' : 'rgba(255,255,255,0.5)', border: '1px solid rgba(255,255,255,0.8)', cursor: 'pointer', transition: 'background 0.15s' }}
              >
                <div style={{ fontSize: 10, fontWeight: 700, color: '#2D6B6B', letterSpacing: '0.1em', textTransform: 'uppercase', marginBottom: 6 }}>{th.trap_label}</div>
                <div style={{ fontSize: 14, color: 'rgba(26,42,42,0.5)', fontStyle: 'italic', lineHeight: 1.55 }}>
                  "{th.user_text?.slice(0, 70)}{th.user_text?.length > 70 ? '…' : ''}"
                </div>
                {expanded === i && (
                  <div style={{ fontSize: 14, color: '#1A2A2A', lineHeight: 1.65, marginTop: 12, paddingTop: 12, borderTop: '1px solid rgba(26,42,42,0.07)', animation: 'fadeIn 0.2s both' }}>
                    {th.reframe}
                  </div>
                )}
              </div>
            ))}
          </>
        )}
      </div>
    </div>
  );
}
